package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class InsetDrawable extends DrawableWrapper { private int l,t,r,b; public InsetDrawable(Drawable d,int inset){this(d,inset,inset,inset,inset);} public InsetDrawable(Drawable d,int l,int t,int r,int b){super(d);this.l=l;this.t=t;this.r=r;this.b=b;} protected void onBoundsChange(Rect q){if(getDrawable()!=null)getDrawable().setBounds(q.left+l,q.top+t,q.right-r,q.bottom-b);} }